(function () {
  'use strict';

  // Prevent duplicate initialization
  if (window.__ZYEKH_CHAT_WIDGET_LOADED__) return;
  window.__ZYEKH_CHAT_WIDGET_LOADED__ = true;

  // Extract runtime configuration from script tag
  const currentScript = document.currentScript || document.querySelector('script[src*="chat-widget"]');
  const API_BASE = currentScript?.getAttribute('data-api') || 'https://api.zyekh.com';
  const PERSONA = currentScript?.getAttribute('data-persona') || 'tech_mentor';
  const CHAT_TITLE = currentScript?.getAttribute('data-title') || (PERSONA === 'tech_mentor' ? 'Zyekh AI Mentor' : PERSONA === 'cloud_assistant' ? 'Zyekh Cloud AI' : 'Zyekh Assistant');
  const CHAT_SUBTITLE = currentScript?.getAttribute('data-subtitle') || 'Online • Technical Advisor';

  const STORAGE_KEY = `zyekh_chat_${PERSONA}_history_v2`;
  const CHAT_ID_KEY = 'zyekh_chat_user_id';

  let userId = localStorage.getItem(CHAT_ID_KEY);
  if (!userId) {
    userId = 'usr_' + Math.random().toString(36).slice(2, 11);
    localStorage.setItem(CHAT_ID_KEY, userId);
  }

  // Inject Design-System-Compliant Styles
  const style = document.createElement('style');
  style.id = 'zyekh-chat-widget-styles';
  style.innerHTML = `
    .zyekh-chat-toggle {
      position: fixed;
      bottom: 24px;
      right: 24px;
      width: 52px;
      height: 52px;
      border-radius: var(--radius-lg, 12px);
      background: var(--bg-card, #141417);
      color: var(--text-main, #fafafa);
      border: 1px solid var(--border-color, #27272a);
      box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 999999;
      transition: border-color var(--transition, 0.2s), transform var(--transition, 0.2s), box-shadow var(--transition, 0.2s);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
    }
    .zyekh-chat-toggle:hover {
      transform: translateY(-2px);
      border-color: var(--border-hover, #52525b);
      box-shadow: 0 14px 36px rgba(0, 0, 0, 0.6);
    }
    .zyekh-chat-toggle svg {
      width: 22px;
      height: 22px;
      fill: none;
      stroke: currentColor;
      stroke-width: 2;
      stroke-linecap: round;
      stroke-linejoin: round;
      transition: transform var(--transition, 0.2s);
    }
    .zyekh-chat-toggle:hover svg {
      transform: scale(1.06);
    }
    .zyekh-chat-window {
      position: fixed;
      bottom: 88px;
      right: 24px;
      width: 390px;
      height: 560px;
      max-width: calc(100vw - 32px);
      max-height: calc(100vh - 110px);
      background: var(--bg-card, #141417);
      border: 1px solid var(--border-color, #27272a);
      border-radius: var(--radius-lg, 12px);
      box-shadow: 0 24px 48px rgba(0, 0, 0, 0.65);
      display: flex;
      flex-direction: column;
      overflow: hidden;
      z-index: 999999;
      font-family: 'Inter', system-ui, -apple-system, sans-serif;
      opacity: 0;
      pointer-events: none;
      transform: translateY(16px) scale(0.97);
      transition: opacity 0.22s cubic-bezier(0.16, 1, 0.3, 1), transform 0.22s cubic-bezier(0.16, 1, 0.3, 1);
    }
    .zyekh-chat-window.open {
      opacity: 1;
      pointer-events: auto;
      transform: translateY(0) scale(1);
    }
    .zyekh-chat-header {
      padding: 14px 16px;
      background: var(--bg-dark, #09090b);
      border-bottom: 1px solid var(--border-color, #27272a);
      display: flex;
      align-items: center;
      justify-content: space-between;
      user-select: none;
    }
    .zyekh-chat-header-info {
      display: flex;
      flex-direction: column;
      gap: 2px;
    }
    .zyekh-chat-header-title {
      font-family: 'Outfit', sans-serif;
      font-size: 0.95rem;
      font-weight: 700;
      color: var(--text-main, #fafafa);
      letter-spacing: -0.015em;
    }
    .zyekh-chat-header-status {
      font-family: 'Fira Code', monospace;
      font-size: 0.72rem;
      color: var(--text-muted, #a1a1aa);
      display: flex;
      align-items: center;
      gap: 6px;
      text-transform: uppercase;
      letter-spacing: 0.04em;
    }
    .zyekh-chat-status-dot {
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: var(--text-muted, #a1a1aa);
      box-shadow: 0 0 6px var(--accent-glow, rgba(255, 255, 255, 0.15));
      display: inline-block;
    }
    .zyekh-chat-header-actions {
      display: flex;
      align-items: center;
      gap: 4px;
    }
    .zyekh-chat-btn-icon {
      width: 28px;
      height: 28px;
      padding: 0;
      margin: 0;
      box-sizing: border-box;
      background: transparent;
      border: 1px solid var(--border-color, #27272a);
      color: var(--text-muted, #a1a1aa);
      cursor: pointer;
      border-radius: var(--radius-sm, 4px);
      display: inline-flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      outline: none;
      transition: color var(--transition, 0.2s), border-color var(--transition, 0.2s), background-color var(--transition, 0.2s);
    }
    .zyekh-chat-btn-icon:hover {
      color: var(--text-main, #fafafa);
      border-color: var(--border-hover, #52525b);
      background: var(--bg-card, #141417);
    }
    .zyekh-chat-btn-icon svg {
      width: 14px;
      height: 14px;
      min-width: 14px;
      min-height: 14px;
      stroke: currentColor;
      stroke-width: 2.2;
      stroke-linecap: round;
      stroke-linejoin: round;
      fill: none;
      display: block;
      pointer-events: none;
    }
    .zyekh-chat-messages {
      flex: 1;
      padding: 16px;
      overflow-y: auto;
      display: flex;
      flex-direction: column;
      gap: 12px;
      scroll-behavior: smooth;
      background: var(--bg-card, #141417);
    }
    .zyekh-chat-bubble {
      max-width: 88%;
      padding: 10px 13px;
      border-radius: var(--radius-md, 6px);
      font-size: 0.84rem;
      line-height: 1.55;
      word-break: break-word;
    }
    .zyekh-chat-bubble.user {
      align-self: flex-end;
      background: var(--border-color, #27272a);
      color: var(--text-main, #fafafa);
      border: 1px solid var(--border-hover, #52525b);
      border-bottom-right-radius: 2px;
    }
    .zyekh-chat-bubble.bot {
      align-self: flex-start;
      background: var(--bg-dark, #09090b);
      color: var(--text-main, #fafafa);
      border: 1px solid var(--border-color, #27272a);
      border-bottom-left-radius: 2px;
    }
    .zyekh-chat-bubble p {
      margin: 0 0 8px 0;
    }
    .zyekh-chat-bubble p:last-child {
      margin-bottom: 0;
    }
    .zyekh-chat-bubble ul, .zyekh-chat-bubble ol {
      margin: 4px 0 8px 18px;
      padding: 0;
    }
    .zyekh-chat-bubble li {
      margin-bottom: 3px;
    }
    .zyekh-chat-bubble code {
      background: var(--code-bg, #000000);
      padding: 2px 5px;
      border-radius: var(--radius-sm, 4px);
      font-family: 'Fira Code', monospace;
      font-size: 0.78rem;
      border: 1px solid var(--border-color, #27272a);
      color: var(--text-main, #fafafa);
    }
    .zyekh-chat-codeblock {
      position: relative;
      background: var(--code-bg, #000000);
      border: 1px solid var(--border-color, #27272a);
      border-radius: var(--radius-sm, 4px);
      margin: 8px 0;
      overflow: hidden;
    }
    .zyekh-chat-codeblock-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 4px 10px;
      background: var(--bg-card, #141417);
      border-bottom: 1px solid var(--border-color, #27272a);
      font-family: 'Fira Code', monospace;
      font-size: 0.7rem;
      color: var(--text-muted, #a1a1aa);
    }
    .zyekh-chat-copy-btn {
      background: transparent;
      border: none;
      color: var(--text-muted, #a1a1aa);
      cursor: pointer;
      font-family: 'Fira Code', monospace;
      font-size: 0.7rem;
      padding: 2px 6px;
      border-radius: var(--radius-sm, 4px);
      transition: color var(--transition, 0.2s);
    }
    .zyekh-chat-copy-btn:hover {
      color: var(--text-main, #fafafa);
    }
    .zyekh-chat-codeblock pre {
      margin: 0;
      padding: 8px 10px;
      overflow-x: auto;
      font-family: 'Fira Code', monospace;
      font-size: 0.76rem;
      line-height: 1.45;
      color: var(--text-main, #fafafa);
    }
    .zyekh-chat-bubble a {
      color: var(--text-main, #fafafa);
      text-decoration: underline;
      text-underline-offset: 3px;
    }
    .zyekh-chat-typing {
      display: flex;
      align-items: center;
      gap: 5px;
      padding: 8px 12px;
      background: var(--bg-dark, #09090b);
      border: 1px solid var(--border-color, #27272a);
      border-radius: var(--radius-md, 6px);
      align-self: flex-start;
      width: fit-content;
    }
    .zyekh-chat-typing span {
      width: 5px;
      height: 5px;
      background: var(--text-muted, #a1a1aa);
      border-radius: 50%;
      animation: zyekhPulse 1.2s infinite ease-in-out;
    }
    .zyekh-chat-typing span:nth-child(2) { animation-delay: 0.2s; }
    .zyekh-chat-typing span:nth-child(3) { animation-delay: 0.4s; }
    @keyframes zyekhPulse {
      0%, 80%, 100% { transform: scale(0.6); opacity: 0.3; }
      40% { transform: scale(1.1); opacity: 1; }
    }
    .zyekh-chat-input-area {
      margin: 0;
      padding: 10px 12px;
      border-top: 1px solid var(--border-color, #27272a);
      background: var(--bg-dark, #09090b);
      display: flex;
      align-items: center;
      gap: 8px;
      box-sizing: border-box;
    }
    .zyekh-chat-input {
      flex: 1;
      height: 38px;
      line-height: 36px;
      box-sizing: border-box;
      background: var(--bg-card, #141417);
      border: 1px solid var(--border-color, #27272a);
      border-radius: var(--radius-sm, 4px);
      padding: 0 12px;
      color: var(--text-main, #fafafa);
      font-family: 'Inter', system-ui, -apple-system, sans-serif;
      font-size: 0.84rem;
      outline: none;
      margin: 0;
      -webkit-appearance: none;
      appearance: none;
      vertical-align: middle;
      transition: border-color var(--transition, 0.2s);
    }
    .zyekh-chat-input:focus {
      border-color: var(--border-hover, #52525b);
    }
    .zyekh-chat-send {
      height: 38px;
      line-height: 36px;
      box-sizing: border-box;
      background: var(--text-main, #fafafa);
      color: var(--bg-dark, #09090b);
      border: 1px solid var(--text-main, #fafafa);
      border-radius: var(--radius-sm, 4px);
      padding: 0 14px;
      font-family: 'Inter', system-ui, -apple-system, sans-serif;
      font-size: 0.8rem;
      font-weight: 600;
      cursor: pointer;
      margin: 0;
      -webkit-appearance: none;
      appearance: none;
      vertical-align: middle;
      transition: opacity var(--transition, 0.2s), background-color var(--transition, 0.2s);
      display: inline-flex;
      align-items: center;
      justify-content: center;
      white-space: nowrap;
      flex-shrink: 0;
    }
    .zyekh-chat-send:hover {
      opacity: 0.9;
    }
    .zyekh-chat-send:disabled {
      opacity: 0.4;
      cursor: not-allowed;
    }

    @media (max-width: 480px) {
      .zyekh-chat-toggle {
        bottom: 16px;
        right: 16px;
      }
      .zyekh-chat-window {
        bottom: 0;
        right: 0;
        width: 100vw;
        height: 100vh;
        max-width: 100vw;
        max-height: 100vh;
        border-radius: 0;
        border: none;
      }
    }
  `;
  document.head.appendChild(style);

  // Markdown & Code formatter with syntax block container
  function formatMarkdown(text) {
    if (!text) return '';
    
    // Extract code blocks first to protect from formatting
    const codeBlocks = [];
    let formatted = text.replace(/```([a-zA-Z0-9_-]*)\n([\s\S]*?)```/g, function (match, lang, code) {
      const id = '__CODE_BLOCK_' + codeBlocks.length + '__';
      const cleanCode = code.replace(/^\n+|\n+$/g, '');
      const language = lang.trim() || 'bash';
      codeBlocks.push({ id, code: cleanCode, lang: language });
      return id;
    });

    // Escape HTML special characters
    formatted = formatted
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');

    // Bold (**text** or *text*)
    formatted = formatted.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
    
    // Inline code (`code`)
    formatted = formatted.replace(/`([^`]+)`/g, '<code>$1</code>');
    
    // Markdown links [text](url)
    formatted = formatted.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');

    // Bullet points (- or *)
    formatted = formatted.replace(/^[\*\-]\s+(.*)$/gm, '<li>$1</li>');
    formatted = formatted.replace(/(<li>.*<\/li>)/s, '<ul>$1</ul>');

    // Paragraph newlines
    formatted = formatted.replace(/\n\n+/g, '</p><p>');
    formatted = formatted.replace(/\n/g, '<br>');
    formatted = '<p>' + formatted + '</p>';
    formatted = formatted.replace(/<p><\/p>/g, '');

    // Re-inject formatted code blocks
    codeBlocks.forEach(function (item) {
      const escapedCode = item.code
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
      
      const blockHtml = `
        <div class="zyekh-chat-codeblock">
          <div class="zyekh-chat-codeblock-header">
            <span>[ ${item.lang.toUpperCase()} ]</span>
            <button type="button" class="zyekh-chat-copy-btn" data-code="${encodeURIComponent(item.code)}">[ Copy ]</button>
          </div>
          <pre><code>${escapedCode}</code></pre>
        </div>
      `;
      formatted = formatted.replace(item.id, blockHtml);
    });

    return formatted;
  }

  // Create UI Structure
  const toggleBtn = document.createElement('button');
  toggleBtn.className = 'zyekh-chat-toggle';
  toggleBtn.setAttribute('aria-label', 'Open AI Assistant');
  toggleBtn.innerHTML = `
    <svg viewBox="0 0 24 24">
      <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"></path>
    </svg>
  `;

  const chatWindow = document.createElement('div');
  chatWindow.className = 'zyekh-chat-window';
  chatWindow.innerHTML = `
    <div class="zyekh-chat-header">
      <div class="zyekh-chat-header-info">
        <div class="zyekh-chat-header-title">${CHAT_TITLE}</div>
        <div class="zyekh-chat-header-status">
          <span class="zyekh-chat-status-dot"></span>
          <span>${CHAT_SUBTITLE}</span>
        </div>
      </div>
      <div class="zyekh-chat-header-actions">
        <button type="button" class="zyekh-chat-btn-icon" id="zyekhChatClear" title="Bersihkan Riwayat" aria-label="Bersihkan Riwayat">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">
            <path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"></path>
            <path d="M3 3v5h5"></path>
          </svg>
        </button>
        <button type="button" class="zyekh-chat-btn-icon" id="zyekhChatClose" title="Tutup Chat" aria-label="Tutup Chat">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">
            <line x1="18" y1="6" x2="6" y2="18"></line>
            <line x1="6" y1="6" x2="18" y2="18"></line>
          </svg>
        </button>
      </div>
    </div>
    <div class="zyekh-chat-messages" id="zyekhChatMessages"></div>
    <form class="zyekh-chat-input-area" id="zyekhChatForm">
      <input type="text" class="zyekh-chat-input" id="zyekhChatInput" placeholder="Tanyakan arsitektur atau tools..." autocomplete="off" />
      <button type="submit" class="zyekh-chat-send" id="zyekhChatSend">Kirim -&gt;</button>
    </form>
  `;

  document.body.appendChild(toggleBtn);
  document.body.appendChild(chatWindow);

  const messagesContainer = chatWindow.querySelector('#zyekhChatMessages');
  const chatForm = chatWindow.querySelector('#zyekhChatForm');
  const chatInput = chatWindow.querySelector('#zyekhChatInput');
  const sendBtn = chatWindow.querySelector('#zyekhChatSend');
  const closeBtn = chatWindow.querySelector('#zyekhChatClose');
  const clearBtn = chatWindow.querySelector('#zyekhChatClear');

  let isOpen = false;

  function loadHistory() {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        const history = JSON.parse(stored);
        if (Array.isArray(history) && history.length > 0) {
          const valid = history.filter(function (m) {
            return m && typeof m.text === 'string' && !m.text.startsWith('[ ERROR ]');
          });
          if (valid.length > 0) {
            valid.forEach(function (msg) {
              if (msg.role === 'user') appendUserMessage(msg.text, false);
              else if (msg.role === 'bot') appendBotMessage(msg.text, false);
            });
            return true;
          }
        }
      }
    } catch (e) {
      console.warn('[Zyekh Chat] History parse error:', e);
    }
    return false;
  }

  function saveMessageToHistory(role, text) {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      const history = stored ? JSON.parse(stored) : [];
      history.push({ role, text, timestamp: Date.now() });
      if (history.length > 30) history.shift();
      localStorage.setItem(STORAGE_KEY, JSON.stringify(history));
    } catch (e) {
      console.warn('[Zyekh Chat] History save error:', e);
    }
  }

  function toggleChat() {
    isOpen = !isOpen;
    chatWindow.classList.toggle('open', isOpen);
    if (isOpen) {
      chatInput.focus();
      if (messagesContainer.children.length === 0) {
        const hasHistory = loadHistory();
        if (!hasHistory) {
          appendBotMessage(
            PERSONA === 'tech_mentor'
              ? 'Halo. Saya Zyekh AI Technical Mentor. Ada yang bisa saya bantu terkait arsitektur zero-trust, tools lokal, atau riset keamanan Linux hari ini?'
              : PERSONA === 'cloud_assistant'
              ? 'Halo. Saya Zyekh Cloud Assistant. Ada file atau aset digital di Google Drive yang ingin Anda cari?'
              : 'Halo. Ada yang bisa kami bantu seputar arsitektur teknis atau tools web hari ini?'
          );
        }
      }
    }
  }

  toggleBtn.addEventListener('click', toggleChat);
  closeBtn.addEventListener('click', toggleChat);

  clearBtn.addEventListener('click', function () {
    localStorage.removeItem(STORAGE_KEY);
    messagesContainer.innerHTML = '';
    appendBotMessage('Riwayat percakapan telah dibersihkan. Silakan ajukan pertanyaan baru.');
  });

  // Copy Code Delegate
  messagesContainer.addEventListener('click', function (e) {
    const copyBtn = e.target.closest('.zyekh-chat-copy-btn');
    if (!copyBtn) return;
    const rawCode = decodeURIComponent(copyBtn.getAttribute('data-code') || '');
    if (navigator.clipboard && rawCode) {
      navigator.clipboard.writeText(rawCode).then(function () {
        const originalText = copyBtn.textContent;
        copyBtn.textContent = '[ Copied! ]';
        setTimeout(function () {
          copyBtn.textContent = originalText;
        }, 1800);
      }).catch(function (err) {
        console.warn('[Zyekh Chat] Clipboard write error:', err);
      });
    }
  });

  function appendUserMessage(text, shouldSave) {
    if (shouldSave === undefined) shouldSave = true;
    const el = document.createElement('div');
    el.className = 'zyekh-chat-bubble user';
    el.textContent = text;
    messagesContainer.appendChild(el);
    messagesContainer.scrollTop = messagesContainer.scrollHeight;
    if (shouldSave) saveMessageToHistory('user', text);
  }

  function appendBotMessage(text, shouldSave) {
    if (shouldSave === undefined) shouldSave = true;
    const el = document.createElement('div');
    el.className = 'zyekh-chat-bubble bot';
    el.innerHTML = formatMarkdown(text);
    messagesContainer.appendChild(el);
    messagesContainer.scrollTop = messagesContainer.scrollHeight;
    if (shouldSave) saveMessageToHistory('bot', text);
  }

  function showTyping() {
    const typing = document.createElement('div');
    typing.className = 'zyekh-chat-typing';
    typing.id = 'zyekhTypingIndicator';
    typing.innerHTML = `<span></span><span></span><span></span>`;
    messagesContainer.appendChild(typing);
    messagesContainer.scrollTop = messagesContainer.scrollHeight;
  }

  function removeTyping() {
    const el = document.getElementById('zyekhTypingIndicator');
    if (el) el.remove();
  }

  chatForm.addEventListener('submit', async function (e) {
    e.preventDefault();
    const text = chatInput.value.trim();
    if (!text) return;

    appendUserMessage(text);
    chatInput.value = '';
    sendBtn.disabled = true;
    showTyping();

    try {
      const res = await fetch(`${API_BASE}/api/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          message: text,
          chatId: userId,
          persona: PERSONA,
          channel: 'web'
        })
      });

      const data = await res.json();
      removeTyping();

      if (data && data.reply) {
        appendBotMessage(data.reply);
      } else {
        appendBotMessage('[ ERROR ] Tidak ada respon yang diterima dari server AI.', false);
      }
    } catch (err) {
      removeTyping();
      appendBotMessage(`[ ERROR ] Gagal terhubung ke API (${err.message || 'Koneksi gagal'}). Pastikan backend AI aktif.`, false);
    } finally {
      sendBtn.disabled = false;
      chatInput.focus();
    }
  });
})();
